import { Select } from '@dreadnought/ui/react';
import { useEffect, useState } from 'react';
function Example() {
  const [search, setSearch] = useState('');
  const [options, setOptions] = useState<{ value: string; label: string }[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError(false);
    fetch('/api/people?q=' + encodeURIComponent(search), { signal: controller.signal })
      .then(response => { if (!response.ok) throw new Error('Search failed'); return response.json(); })
      .then(results => { if (!controller.signal.aborted) setOptions(results); })
      .catch(() => { if (!controller.signal.aborted) { setOptions([]); setError(true); } })
      .finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [search]);
  return <Select aria-label='Исполнитель' options={options} searchable searchValue={search} onSearch={setSearch} filterOption={false} loading={loading} emptyContent={error ? 'Не удалось загрузить варианты' : 'Нет вариантов'} />;
}
